static const char free_comp[] =
    "#version 310 es\n"
    "// Boing Swarm, step 1: each boid flies to its place on the spinning ball,\n"
    "// with no neighbours (the simulation's floor cost).\n"
    "layout(local_size_x = 128) in;\n"
    "struct Boid { vec4 pos; vec4 vel; };\n"
    "layout(std430, binding = 0) readonly buffer Src { Boid b[]; } src;\n"
    "layout(std430, binding = 1) writeonly buffer Dst { Boid b[]; } dst;\n"
    "layout(rgba32f, binding = 0) writeonly uniform highp image2D u_img;\n"
    "uniform int u_n;\n"
    "uniform float u_dt;\n"
    "uniform float u_spin;\n"
    "uniform vec3 u_centre;\n"
    "\n"
    "// Boid i's place on a ball of radius 3 (a Fibonacci sphere), spun about the\n"
    "// tilted axis; w: 1 for a red check, 0 for a white one. (Computed: faster\n"
    "// than read from a buffer made once, 2.7 against 3.1 ms at 16384 boids.)\n"
    "vec4 home(int i)\n"
    "{\n"
    "    float y = 1.0 - 2.0 * (float(i) + 0.5) / float(u_n);\n"
    "    float r = sqrt(max(1.0 - y * y, 0.0));\n"
    "    float phi = mod(float(i) * 2.3999632, 6.2831853);\n"
    "    float lon = mod(phi + u_spin, 6.2831853);\n"
    "    float check = mod(floor(phi * 2.5464791) + floor((y + 1.0) * 4.0), 2.0);\n"
    "    vec3 p = vec3(cos(lon) * r, y, sin(lon) * r) * 3.0;\n"
    "    float c = 0.9553365, s = 0.2955202; // the 1984 ball's tilt, 0.3 rad\n"
    "    return vec4(u_centre + vec3(c * p.x - s * p.y, s * p.x + c * p.y, p.z), check);\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    int i = int(gl_GlobalInvocationID.x);\n"
    "    if (i >= u_n)\n"
    "        return;\n"
    "    vec4 h = home(i);\n"
    "    vec3 p = src.b[i].pos.xyz, v = src.b[i].vel.xyz;\n"
    "    v += ((h.xyz - p) * 9.0 - v * 4.0) * u_dt;\n"
    "    p += v * u_dt;\n"
    "    dst.b[i].pos = vec4(p, h.w);\n"
    "    dst.b[i].vel = vec4(v, 0.0);\n"
    "    imageStore(u_img, ivec2(i & 127, i >> 7), vec4(p, h.w));\n"
    "}\n"
    ;

